package com.edunexa.app
import android.os.Bundle
import android.text.InputType
import android.widget.*
import androidx.appcompat.app.AppCompatActivity
import com.edunexa.app.data.SchoolResultRepository
class PublishResultActivity:AppCompatActivity(){private val repo=SchoolResultRepository();private fun dp(v:Int)=(v*resources.displayMetrics.density).toInt();override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);val root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(18),dp(18),dp(18),dp(18))};setContentView(ScrollView(this).apply{addView(root)});root.addView(TextView(this).apply{text="Publish Results";textSize=27f;setTypeface(typeface,1)});val student=Spinner(this);val exam=EditText(this).apply{hint="Exam / Term"};val subject=EditText(this).apply{hint="Subject"};val obtained=EditText(this).apply{hint="Obtained marks";inputType=InputType.TYPE_CLASS_NUMBER or InputType.TYPE_NUMBER_FLAG_DECIMAL};val total=EditText(this).apply{hint="Total marks";inputType=InputType.TYPE_CLASS_NUMBER or InputType.TYPE_NUMBER_FLAG_DECIMAL};val status=TextView(this).apply{setPadding(0,dp(8),0,dp(8))};root.addView(student);root.addView(exam);root.addView(subject);root.addView(obtained);root.addView(total);root.addView(Button(this).apply{text="Publish Result";isAllCaps=false;setOnClickListener{val item=student.selectedItem as? StudentItem?:return@setOnClickListener;val a=obtained.text.toString().toDoubleOrNull()?:-1.0;val b=total.text.toString().toDoubleOrNull()?:0.0;if(exam.text.isBlank()||subject.text.isBlank()||a<0||b<=0||a>b){status.text="Enter valid exam, subject and marks";return@setOnClickListener};repo.publish(item.id,item.name,exam.text.toString(),subject.text.toString(),a,b){ok,m->status.text=m;if(ok){subject.text.clear();obtained.text.clear();total.text.clear()}}}});root.addView(status);repo.students({rows->student.adapter=ArrayAdapter(this,android.R.layout.simple_spinner_dropdown_item,rows.map{StudentItem(it.first,it.second)});if(rows.isEmpty())status.text="No connected students"},{status.text=it})}data class StudentItem(val id:String,val name:String){override fun toString()=name}}
